9e95}.band-95{stroke:#b1c7bb}.median{fill:#fff;stroke:#385c46;stroke-width:2}.anchor-line{stroke:#b6b9aa;stroke-dasharray:4 5}.level{font-size:11px;fill:#76836f}.band-label{font-size:12px;fill:#5f755d}details{font-size:12px;line-height:1.9;margin-top:16px;border-top:1px solid #edf0e8;padding-top:12px}summary{cursor:pointer;color:#607b61;font-weight:700}.validation p{color:#83917c}.scenario-view{padding:12px 15px;border-left:3px solid currentColor;margin-top:10px;border-radius:0 8px 8px 0}.scenario-view h4{margin:0}.scenario-view p{font-size:12px;line-height:1.9}.sample{font-size:10px}@media(max-width:650px){.shared-distribution{margin:15px 12px;padding:16px}.shared-distribution header{flex-direction:column}h3{font-size:20px}.shared-probabilities{gap:7px}.shared-probabilities article{padding:14px 6px}.shared-probabilities strong{font-size:28px}.shared-probabilities em{font-size:14px}.shared-probabilities p{font-size:9px}.method-tag{font-size:10px}}
